INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 13, 'theory', 'Quiz: testing and code style');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 13, 0, 'What should a test executable return so that the build can determine the result automatically?', '["Always 0", "The number of tests passed", "Code 0 on success and a nonzero code on any failure", "The size of the output"]', 2, 'Build systems and continuous integration look only at the exit code: 0 means all is well, anything else is a failure.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 13, 1, 'When should you use assert, and when should you return an error code?', '["assert for contract violations (program bugs), an error code for invalid user input and environment failures", "assert for user input, an error code for bugs", "Always assert", "Always an error code, assert is not needed"]', 0, 'A violated precondition is a bug in the calling code: stop with a message. Invalid input is a normal situation, and the caller should get an error code.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 13, 2, 'Why plug an allocator that fails on the n-th call into tests?', '["To make the tests run faster", "To turn off the sanitizer", "To increase coverage of the normal path", "To check the out-of-memory branches: the function must free everything and return an error"]', 3, 'The "malloc returned NULL" branches are never executed in ordinary tests. Fault injection checks that there are no leaks or corruption on every path.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 13, 3, 'Why does 100% line coverage not guarantee the quality of tests?', '["Because gcov makes mistakes", "Because a test can run the code and check nothing", "Because coverage ignores comments", "Because coverage is computed only for functions"]', 1, 'Coverage shows that lines were executed, not that the result was checked. Mutation testing and meaningful assertions complement it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 13, 4, 'Which approach to resources is good practice in a function with several allocations?', '["Free by hand on every path with no single exit point", "A single cleanup block at the end with goto cleanup, where all resources are released", "Do not free anything — the system will do it at exit", "A flag variable and if statements nested five levels deep"]', 1, 'One cleanup block avoids duplicated frees and forgotten paths. Pointers handed over to the caller are set to NULL after the handover so they are not freed twice.');
